  'pricing.faq.trialQ': '¿Cómo funciona la prueba gratuita de 7 días?',
  'pricing.faq.trialA': 'Todas las cuentas nuevas obtienen automáticamente una prueba gratuita de 7 días, sin necesidad de código. Deberá introducir los datos de su tarjeta, pero no se le cobrará durante esos 7 días. Después, la suscripción comenzará automáticamente. Puede cancelarla en cualquier momento durante la prueba.',
  'pricing.faq.cancelQ': '¿Puedo cancelar mi suscripción en cualquier momento?',
  'pricing.faq.cancelA': '¡Sí! Puede cancelar en cualquier momento desde su configuración. La suscripción permanece activa hasta el final del período actual.',
  'pricing.faq.limitQ': '¿Hay límite de alumnos?',
  'pricing.faq.limitA': '¡No! Puede tener un número ilimitado de alumnos. Solo paga la suscripción, no por cada alumno.',
  'pricing.faq.paymentQ': '¿Qué métodos de pago se aceptan?',
  'pricing.faq.paymentA': 'Aceptamos las principales tarjetas de crédito y débito a través de Stripe, que protege los pagos mediante 3D Secure.',
